import React from "react";
import { useNavigate } from "react-router-dom";
import "./style/Comparison.css";

function Comparison() {
  const navigate = useNavigate();

  // بيانات افتراضية مؤقتة (سيتم استبدالها بنتائج حقيقية لاحقًا)
  const data = [
    { method: "الخوارزمية الجينية", accuracy: "94%", color: "#be185d" },
    { method: "Mutual Information (sklear feature_selection ) ", accuracy: "91%", color: "#ec4899" },
    { method: "PCA (Principal Components analysis)", accuracy: "89%", color: "#f472b6" },
  ];

  return (
    <div className="comparison-container">
      <h1 className="comparison-title">مقارنة بين طرق اختيار الخصائص</h1>

      <p className="comparison-description">
        يوضح الجدول التالي مقارنة في دقة النموذج عند استخدام طرق مختلفة لاختيار
        الخصائص من بيانات سرطان الثدي.
      </p>

      <table className="comparison-table">
        <thead>
          <tr>
            <th>الطريقة</th>
            <th>دقة النموذج</th>
          </tr>
        </thead>
        <tbody>
          {data.map((row, index) => (
            <tr key={index}>
              <td style={{ color: row.color, fontWeight: "bold" }}>
                {row.method}
              </td>
              <td>{row.accuracy}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <button onClick={() => navigate("/results")} className="comparison-btn">
        العودة إلى النتائج
      </button>
    </div>
  );
}

export default Comparison;
